@pytest.mark.parametrize("args", [[], ["-l"], ["-L", "default"]])
def test_not_in_project(args, script_runner):
    ret = script_runner.run("scrapyd-deploy", *args)

    assert ret.stdout == ""
    assertLines(ret.stderr, "Error: no Scrapy project found in this location")
    assert not ret.success

@pytest.mark.parametrize(
    "url,username,password,expected",
    [
        ("http://localhost:6800", None, None, None),
        (
            "http://localhost:6800",
            "user",
            "pass",
            HTTPBasicAuth("user", "pass"),
        ),
    ],
)
def test_get_auth(url, username, password, expected):
    assert get_auth(url, username, password) == expected
